solution.Solution.cs:
public static class Calendar
{
    static bool IsWorkDay(DateOnly d) => d.DayOfWeek is not (DayOfWeek.Saturday or DayOfWeek.Sunday);

    public static int WorkingDays(DateOnly from, DateOnly to)
    {
        int count = 0;
        for (var d = from; d < to; d = d.AddDays(1))
            if (IsWorkDay(d)) count++;
        return count;
    }

    public static DateOnly AddWorkingDays(DateOnly start, int days)
    {
        if (days < 0) throw new ArgumentOutOfRangeException(nameof(days));
        var d = start;
        while (!IsWorkDay(d)) d = d.AddDays(1);
        while (days > 0)
        {
            d = d.AddDays(1);
            if (IsWorkDay(d)) days--;
        }
        return d;
    }
}

unitTests:
var fri = new DateOnly(2026, 11, 20);

Test("a week", () =>
{
    CheckEq(Calendar.WorkingDays(new DateOnly(2026, 11, 16), new DateOnly(2026, 11, 23)), 5);
});

Test("over a weekend", () =>
{
    CheckEq(Calendar.WorkingDays(fri, new DateOnly(2026, 11, 24)), 2);
    CheckEq(Calendar.WorkingDays(fri, fri), 0);
    CheckEq(Calendar.WorkingDays(fri, new DateOnly(2026, 11, 1)), 0);
});

Test("adding working days", () =>
{
    CheckEq(Calendar.AddWorkingDays(fri, 1), new DateOnly(2026, 11, 23));
    CheckEq(Calendar.AddWorkingDays(fri, 5), new DateOnly(2026, 11, 27));
    CheckEq(Calendar.AddWorkingDays(new DateOnly(2026, 11, 21), 0), new DateOnly(2026, 11, 23));
    CheckThrows<ArgumentOutOfRangeException>(() => Calendar.AddWorkingDays(fri, -1));
});

